let D={projects:[],testimonials:[],messages:[],conversations:[],settings:{}};let activeChat=null;let sortBusy=false;let dragState=null;
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});const t=await r.text();let j={};try{j=t?JSON.parse(t):{}}catch{}if(!r.ok)throw Error(j.error||'Request failed');return j}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.__toast);window.__toast=setTimeout(()=>e.style.display='none',2200)}
function tab(id){$$('.section').forEach(x=>x.classList.toggle('active',x.id===id));$$('.side-nav button[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));const names={dashboard:'Dashboard',projects:'Projects / Case Studies',services:'Services',about:'About Me',skills:'Skills & Technologies',marquee:'Marquee Logos',process:'Process Steps',metrics:'Metrics & Stats',visualFlow:'Estimator',testimonials:'Testimonials',pages:'Blog / Articles',media:'Media Library',navigation:'Navigation',messages:'Contact Messages',chat:'Live Chat',payments:'Payments',transactions:'Transactions',withdraw:'Withdraw / Payouts',invoices:'Invoices',appearance:'Appearance',seo:'SEO Settings',analytics:'Analytics',hosting:'Domain & Hosting',general:'General Settings',users:'Users & Permissions'};$('#pageTitle').textContent=names[id]||'Dashboard';$('#pageSubtitle').textContent=id==='dashboard'?'Welcome back, Ethon! 👋':'Manage '+(names[id]||'your website').toLowerCase();if(id==='messages')renderMessages();if(id==='chat')renderChats();if(id==='transactions')renderTransactions()}
function fillSettings(){const s=D.settings||{};$$('.setting').forEach(e=>{const k=e.dataset.key;if(k)e.value=s[k]??''});$$('.setting-check').forEach(e=>e.checked=s[e.dataset.key]!==false);$$('.json-setting').forEach(e=>{const k=e.dataset.key;let v=s[k]??[];e.value=typeof v==='string'?v:JSON.stringify(v,null,2)});const all=$('#allSettingsJson');if(all)all.value=JSON.stringify(s,null,2);buildSocialFields();buildCollectionEditors();buildAboutOrderEditor();buildGatewayOrderEditor();buildFlowEditors()}
const social=[['fiverr','Fiverr'],['freelancer','Freelancer'],['linkedin','LinkedIn'],['dribbble','Dribbble'],['behance','Behance'],['github','GitHub'],['whatsapp','WhatsApp'],['email','Email'],['facebook','Facebook'],['instagram','Instagram'],['twitter','X / Twitter'],['upwork','Upwork']];
const socialIconMap={fiverr:'fiverr.svg',freelancer:null,linkedin:'linkedin.svg',dribbble:'dribbble.svg',behance:'behance.svg',github:'github.svg',whatsapp:'whatsapp.svg',email:null,facebook:'facebook.svg',instagram:'instagram.svg',twitter:'x-twitter.svg',upwork:'upwork.svg'};
function socialItems(){const s=D.settings||{},custom=Array.isArray(s.customSocialLinks)?s.customSocialLinks:[];const byKey={};social.forEach(([k,l])=>byKey[k]={key:k,label:l,url:String(s[k]||''),icon:'',builtin:true});custom.forEach(x=>{if(x&&x.key)byKey[x.key]={key:String(x.key),label:String(x.label||x.key),url:String(x.url||''),icon:String(x.icon||''),builtin:false}});let order=Array.isArray(s.socialOrder)?s.socialOrder:[];order=[...order,...Object.keys(byKey).filter(k=>!order.includes(k))];return order.map(k=>byKey[k]).filter(x=>x&&x.url)}
function socialIcon(item){const file=socialIconMap[item.key];if(item.icon)return `<img src="${esc(item.icon)}" alt="">`;return file?`<img src="assets/social/${file}" alt="">`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.1.1l2-2a5 5 0 0 0-7.1-7.1l-1.2 1.2"></path><path d="M14 11a5 5 0 0 0-7.1-.1l-2 2A5 5 0 0 0 12 20l1.2-1.2"></path></svg>`}
function buildSocialFields(){const root=$('#socialFields');if(!root)return;const items=socialItems();root.innerHTML=items.length?items.map(x=>`<div class="social-row" draggable="true" data-social-key="${esc(x.key)}" data-builtin="${x.builtin?'1':'0'}"><span class="social-drag" title="Drag to reorder">☷</span><span class="social-icon">${socialIcon(x)}</span><input class="field social-label" data-key="${esc(x.key)}" value="${esc(x.label)}" placeholder="Name"><input class="field social-url" data-key="${esc(x.key)}" value="${esc(x.url)}" placeholder="Link / URL"><input class="field social-icon-url" data-key="${esc(x.key)}" value="${esc(x.icon||'')}" placeholder="Icon URL (SVG/PNG)"><button class="btn social-remove" type="button" data-remove-social="${esc(x.key)}">Remove</button></div>`).join(''):'<div class="social-empty">No social links added yet.</div>';bindSocialEditor(root)}
function bindSocialEditor(root){
 if(!root||root.dataset.bound)return;root.dataset.bound='1';let drag=null;
 const clearDrag=()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(drag){drag.classList.remove('dragging');drag=null}};
 const saveOrder=async()=>{try{const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(readSocialSettings())});D.settings=out;toast('Social position saved ✓')}catch(e){toast(e.message)}};
 root.addEventListener('dragstart',e=>{drag=e.target.closest('.social-row');if(drag){e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',drag.dataset.socialKey)}catch{}drag.classList.add('dragging')}});
 root.addEventListener('dragover',e=>{const t=e.target.closest('.social-row');if(!drag||!t||t===drag)return;e.preventDefault();t.classList.add('drag-over');const r=t.getBoundingClientRect();root.insertBefore(drag,e.clientY<r.top+r.height/2?t:t.nextSibling)});
 root.addEventListener('drop',async e=>{if(!drag)return;e.preventDefault();clearDrag();await saveOrder()});
 root.addEventListener('dragend',clearDrag);
 root.addEventListener('click',e=>{const b=e.target.closest('[data-remove-social]');if(!b)return;const key=b.dataset.removeSocial;root.querySelector(`.social-row[data-social-key="${CSS.escape(key)}"]`)?.remove();if(!root.querySelector('.social-row'))root.innerHTML='<div class="social-empty">No social links added yet.</div>'});
}
function readSocialSettings(){const root=$('#socialFields');const rows=[...root.querySelectorAll('.social-row')];const out={socialOrder:rows.map(r=>r.dataset.socialKey),customSocialLinks:[]};social.forEach(([k])=>out[k]='');rows.forEach(r=>{const key=r.dataset.socialKey,label=r.querySelector('.social-label')?.value.trim()||key,url=r.querySelector('.social-url')?.value.trim()||'',icon=r.querySelector('.social-icon-url')?.value.trim()||'';const built=social.some(x=>x[0]===key);if(built)out[key]=url;else out.customSocialLinks.push({key,label,url,icon})});return out}
function buildAboutOrderEditor(){const root=$('#aboutOrderEditor');if(!root)return;const fallback=['photo','content'],order=Array.isArray(D.settings?.aboutLayoutOrder)?D.settings.aboutLayoutOrder.filter(x=>fallback.includes(x)):fallback;const normalized=[...order,...fallback.filter(x=>!order.includes(x))];root.innerHTML=normalized.map((x,i)=>`<div class="collection-row sortable-item about-order-row" draggable="true" data-about-key="${x}"><span class="sortable-handle">Drag</span><div><strong>${x==='photo'?'About Image / Photo':'About Text / Content'}</strong><small class="muted" style="display:block;margin-top:4px;font-size:8px">${x==='photo'?'Left visual block':'Right information + skills block'}</small></div></div>`).join('');bindAboutSortable(root)}
function bindAboutSortable(root){if(!root||root.dataset.sortBound)return;root.dataset.sortBound='1';let item=null;root.addEventListener('dragstart',e=>{item=e.target.closest('.about-order-row');if(item){item.classList.add('dragging');e.dataTransfer.effectAllowed='move'}});root.addEventListener('dragover',e=>{const target=e.target.closest('.about-order-row');if(!item||!target||target===item)return;e.preventDefault();target.classList.add('drag-over');const r=target.getBoundingClientRect();root.insertBefore(item,e.clientY<r.top+r.height/2?target:target.nextSibling)});root.addEventListener('drop',async e=>{if(!item)return;e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const order=[...root.querySelectorAll('.about-order-row')].map(x=>x.dataset.aboutKey);item.classList.remove('dragging');item=null;sortBusy=true;try{const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({aboutLayoutOrder:order})});D.settings=out;applyAboutLayoutPreview(order);toast('About order saved ✓')}catch(e){toast(e.message);await load()}finally{sortBusy=false}});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(item){item.classList.remove('dragging');item=null}})}
function applyAboutLayoutPreview(order){const root=document.querySelector('#aboutOrderEditor');if(!root)return;const seq=Array.isArray(order)?order:['photo','content'];root.innerHTML=seq.map(x=>`<div class="collection-row sortable-item about-order-row" draggable="true" data-about-key="${x}"><span class="sortable-handle">Drag</span><div><strong>${x==='photo'?'About Image / Photo':'About Text / Content'}</strong><small class="muted" style="display:block;margin-top:4px;font-size:8px">${x==='photo'?'Left visual block':'Right information + skills block'}</small></div></div>`).join('');bindAboutSortable(root)}

async function saveSettings(){try{let b={};const all=$('#allSettingsJson');if(all&&all.value.trim()){try{b=JSON.parse(all.value)}catch{throw Error('Advanced A–Z JSON is invalid')}}$$('.setting').forEach(e=>{if(e.dataset.key)b[e.dataset.key]=e.value});$$('.setting-check').forEach(e=>b[e.dataset.key]=e.checked);$$('.json-setting').forEach(e=>{const k=e.dataset.key;try{b[k]=JSON.parse(e.value||'[]')}catch{throw Error('Invalid JSON in '+k)}});if($('#socialFields'))Object.assign(b,readSocialSettings());
 let f=$('#heroImageFile')?.files?.[0];if(f)b.heroImage=await uploadFile(f,4);let cv=$('#cvFile')?.files?.[0];if(cv)b.heroTertiaryHref=await uploadFile(cv,12);let vf=$('#videoFile')?.files?.[0];if(vf)b.videoUrl=await uploadFile(vf,60);let vp=$('#videoPosterFile')?.files?.[0];if(vp)b.videoPoster=await uploadFile(vp,4);
 const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(b)});D.settings=out;fillSettings();toast('All website changes saved ✓')}catch(e){toast(e.message)}}
async function uploadFile(file,mb){if(file.size>mb*1024*1024)throw Error(`File must be under ${mb}MB`);return new Promise((ok,no)=>{const r=new FileReader;r.onload=async()=>{try{const x=await api('/api/admin/media',{method:'POST',body:JSON.stringify({data:r.result,name:file.name})});ok(x.url)}catch(e){no(e)}};r.onerror=no;r.readAsDataURL(file)})}
const FX_TO_USD={USD:1,GBP:1.34,EUR:1.16,BDT:0.0082};
const CURRENCY_SYMBOL={USD:'$',GBP:'£',EUR:'€',BDT:'৳'};
function money(n,c){const v=(Number(n)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});return (CURRENCY_SYMBOL[c]||c+' ')+v+(c==='BDT'?' BDT':'')}
function toUSD(amount,c){return (Number(amount)||0)*(FX_TO_USD[String(c||'USD').toUpperCase()]||1)}
function fromUSD(amount,c){const code=String(c||'USD').toUpperCase();return (Number(amount)||0)/(FX_TO_USD[code]||1)}
function selectedDashboardCurrency(){return localStorage.getItem('ethonDashboardCurrency')||'USD'}
function paymentTotals(){const rows=(D.messages||[]).filter(x=>x.type==='payment');const out={paidUSD:0,pendingUSD:0,cancelledUSD:0};rows.forEach(x=>{const amount=Number(x.amount||String(x.budget||'').match(/[0-9]+(?:\.[0-9]+)?/)?.[0]||0);const c=String(x.currency||((x.budget||'').match(/USD|GBP|EUR|BDT/)||['USD'])[0]).toUpperCase();const st=x.status||'pending';if(st==='paid')out.paidUSD+=toUSD(amount,c);else if(st==='cancelled')out.cancelledUSD+=toUSD(amount,c);else out.pendingUSD+=toUSD(amount,c)});return out}
function renderVisitorChart(history){const area=$('#chartArea'),line=$('#chartLine'),spark=document.querySelector('.spark path');if(!area||!line)return;const rows=Array.isArray(history)?history.slice(-20):[];if(!rows.length){area.setAttribute('d','M0 130 V150H0Z');line.setAttribute('d','M0 130');return}const vals=rows.map(x=>Number(x.count||0)),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(1,max-min),W=560,H=150,padY=18;const pts=vals.map((v,i)=>{const x=rows.length===1?0:(i/(rows.length-1))*W;const y=H-padY-((v-min)/range)*(H-padY*2);return [x,y]});const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');line.setAttribute('d',d);area.setAttribute('d',d+' V150H0Z');if(spark){const sw=120,sh=45;const sd=pts.map((p,i)=>{const x=(i/Math.max(1,pts.length-1))*sw;const y=8+(p[1]/H)*(sh-14);return (i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}).join(' ');spark.setAttribute('d',sd)}}
function getMessageStats(){const contacts=(D.messages||[]).filter(x=>x.type!=='payment');const chat=(D.conversations||[]).flatMap(c=>Array.isArray(c.messages)?c.messages:[]).filter(m=>m.channel==='chat'&&m.from==='visitor');return{contactCount:contacts.length,contactUnread:contacts.filter(x=>!x.read).length,chatCount:chat.length,chatUnread:(D.conversations||[]).reduce((n,c)=>n+Number(c.chatUnread||0),0),total:contacts.length+chat.length}}
function renderDashboard(){const p=D.projects||[],m=D.messages||[],s=D.settings||{},v=Number(s.visitorCount||0),cv=Number(s.cvDownloads||0),pv=Number(s.profileViews||0),t=paymentTotals(),q=getMessageStats(),cur=selectedDashboardCurrency();const cvEl=$('#dashboardCurrency');if(cvEl)cvEl.value=cur;const paid=fromUSD(t.paidUSD,cur),pending=fromUSD(t.pendingUSD,cur),cancelled=fromUSD(t.cancelledUSD,cur),total=paid+pending+cancelled;$('#statProjects').textContent=p.length;renderVisitorChart(s.visitorHistory||[]);$('#statVisitors').textContent=v>=1000?(v/1000).toFixed(v>=10000?0:1)+'K':v;$('#statProfileViews').textContent=pv>=1000?(pv/1000).toFixed(1)+'K':pv;$('#statMessages').textContent=q.total;$('#messageBadge').textContent=Math.min(99,q.contactUnread);$('#chatBadge').textContent=Math.min(99,q.chatUnread);$('#statCvDownloads').textContent=cv;$('#statEarnings').textContent=money(paid,cur);$('#statEarningsBdt').textContent='Selected: '+cur;$('#statVisitorsGrowth').textContent='Live visitor count';$('#statMessagesGrowth').innerHTML=`<span>Contact: ${q.contactCount}</span><i></i><span class="live-chat-count">Live Chat: ${q.chatCount}</span>`;$('#chartVisitors').textContent=v.toLocaleString();$('#chartVisitorsGrowth').textContent='Live tracking';$('#paidSummary').textContent=money(paid,cur);$('#pendingSummary').textContent=money(pending,cur);$('#cancelledSummary').textContent=money(cancelled,cur);$('#paidBdtSummary').textContent=money(total,cur);$('#availableUsd').textContent=money(paid,cur);$('#pendingUsd').textContent=money(pending,cur);$('#availableBdt').textContent=money(paid,cur);$('#recentProjects').innerHTML=p.slice(-4).reverse().map(x=>`<div class="project-row"><img class="project-thumb" src="${esc(x.image||'assets/logo.png')}"><div class="project-copy"><strong>${esc(x.title)}</strong><small><span class="status">${x.published===false?'Hidden':'Published'}</span> &nbsp;•&nbsp; ${esc(x.category||'Project')}</small></div><div class="row-right">${x.live?'↗':''} ${x.featured?'★':''}</div></div>`).join('')||'<p class="muted" style="padding:12px">No projects yet.</p>';$('#recentMessages').innerHTML=m.slice(0,4).map(x=>`<div class="message-row"><div class="avatar" style="display:grid;place-items:center">${esc((x.name||'?').slice(0,1).toUpperCase())}</div><div class="message-copy"><strong>${esc(x.name)}</strong><small>${esc(x.message||'').slice(0,70)}</small></div><div class="message-time">${timeAgo(x.createdAt)}</div><div class="dot"></div></div>`).join('')||'<p class="muted" style="padding:12px">No messages.</p>'}

function timeAgo(ts){if(!ts)return'';const d=(Date.now()-new Date(ts).getTime())/60000;if(d<1)return'now';if(d<60)return Math.round(d)+'m ago';if(d<1440)return Math.round(d/60)+'h ago';return Math.round(d/1440)+'d ago'}
function renderProjects(){const list=$('#projectList');if(!list)return;list.innerHTML=D.projects.map(x=>`<div class="item sortable-item" draggable="true" data-sort-id="${esc(x.id)}"><span class="sortable-handle">Drag</span>${x.image?`<img class="thumb" src="${esc(x.image)}">`:''}<h3>${esc(x.title)}</h3><span class="pill">${esc(x.category||'Project')}</span> <span class="muted" style="font-size:9px">${x.published===false?'Hidden':'Published'}</span><p>${esc(x.description||'')}</p><div class="actions"><button class="btn ghost" onclick="openProject('${x.id}')">Edit</button><button class="btn danger" onclick="del('projects','${x.id}')">Delete</button></div></div>`).join('')||'<p class="muted" style="padding:15px">No projects.</p>';bindSortable(list,'projects')}
