function renderServices(){let s=D.settings?.services||[];const root=$('#serviceList');root.innerHTML=s.map((x,i)=>`<div class="item sortable-item" draggable="true" data-sort-index="${i}"><span class="sortable-handle">Drag</span><h3>${esc(x.title)}</h3><span class="pill">${x.enabled===false?'Hidden':'Visible'}</span><p>${esc(x.description||'')}</p><div class="actions"><button class="btn ghost" onclick="editService(${i})">Edit</button><button class="btn danger" onclick="removeService(${i})">Delete</button></div></div>`).join('')||'<p class="muted" style="padding:15px">No services.</p>';bindServiceSortable(root)}
function bindServiceSortable(root){if(!root||root.dataset.sortBound)return;root.dataset.sortBound='1';let item=null;root.addEventListener('dragstart',e=>{item=e.target.closest('.sortable-item');if(item){item.classList.add('dragging');e.dataTransfer.effectAllowed='move'}});root.addEventListener('dragover',e=>{const target=e.target.closest('.sortable-item');if(!item||!target||target===item)return;e.preventDefault();target.classList.add('drag-over');const r=target.getBoundingClientRect();root.insertBefore(item,e.clientY<r.top+r.height/2?target:target.nextSibling)});root.addEventListener('drop',async e=>{if(!item)return;e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const services=D.settings?.services||[];const order=[...root.querySelectorAll('.sortable-item')].map(x=>Number(x.dataset.sortIndex));const reordered=order.map(i=>services[i]).filter(Boolean);item.classList.remove('dragging');item=null;sortBusy=true;try{const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({services:reordered})});D.settings=out;renderServices();toast('Service order saved ✓')}catch(err){toast(err.message);await load()}finally{sortBusy=false}});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(item){item.classList.remove('dragging');item=null}})}
function buildGatewayOrderEditor(){const root=$('#gatewayOrderEditor');if(!root)return;const fallback=['STRIPE','PAYPAL','PAYONEER','GOOGLE PAY','BINANCE PAY','BKASH'];const labels={STRIPE:'Stripe (Card)',PAYPAL:'PayPal',PAYONEER:'Payoneer','GOOGLE PAY':'Google Pay','BINANCE PAY':'Binance Pay',BKASH:'bKash'};const order=Array.isArray(D.settings?.paymentGatewayOrder)?D.settings.paymentGatewayOrder.filter(x=>fallback.includes(x)):fallback;const normalized=[...order,...fallback.filter(x=>!order.includes(x))];root.innerHTML=normalized.map(x=>`<div class="collection-row sortable-item gateway-order-row" draggable="true" data-gateway-key="${x}"><span class="sortable-handle">Drag</span><div><strong>${labels[x]||x}</strong></div></div>`).join('');bindGatewaySortable(root)}
