async function markRead(id){await api('/api/admin/messages/'+id,{method:'PATCH',body:JSON.stringify({read:true})});await load();tab('messages');toast('Message marked read')}
function renderChats(){const l=$('#chatList');l.innerHTML=(D.conversations||[]).map(x=>`<div class="chat-user ${activeChat===x.id?'active':''}" onclick="selectChat('${x.id}')"><strong>${esc(x.name)} ${Number(x.chatUnread||0)>0?`<span class="pill" style="float:right">${Math.min(99,Number(x.chatUnread||0))} new</span>`:''}</strong><small>${esc(x.email)} • ${timeAgo(x.updatedAt)}</small></div>`).join('')||'<p class="muted" style="padding:10px">No conversations yet.</p>'}
async function selectChat(id){activeChat=id;const c=(D.conversations||[]).find(x=>x.id===id);$('#chatHeader h2').textContent=c?c.name:'Conversation';try{const ms=await api('/api/chat/'+id);$('#chatMessages').innerHTML=ms.map(m=>{const isAdmin=m.from==='admin',at=Array.isArray(m.attachments)?m.attachments:[],files=at.map(x=>`<div class="chat-attachment"><a href="${esc(x.url)}" target="_blank" rel="noopener">↗ ${esc(x.name)}</a><a class="chat-attachment-download" href="/api/chat/download?file=${encodeURIComponent(String(x.url||'').replace(/^\/uploads\//,''))}" download title="Download file" aria-label="Download file"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11m0 0 4-4m-4 4-4-4M5 18.5h14"/></svg></a></div>`).join('');return `<div class="chat-message-row ${isAdmin?'admin-row':'visitor-row'}"><div class="bubble ${isAdmin?'admin':''}">${m.text?esc(m.text):''}${files}<div style="opacity:.45;font-size:8px;margin-top:3px">${new Date(m.createdAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</div></div><img class="chat-msg-avatar" src="${isAdmin?'assets/ethon-admin-avatar.webp':'assets/chat-ghost-avatar.svg'}" alt="${isAdmin?'Ethon':'Client'}"></div>`}).join('');$('#chatMessages').scrollTop(1e9);await api('/api/admin/conversations/'+id+'/read',{method:'POST'});if(c)c.chatUnread=0;renderDashboard()}catch{}renderChats()}
async function renderTransactions(){const rows=(D.messages||[]).filter(x=>x.type==='payment');$('#transactionList').innerHTML=rows.map(x=>{const st=x.status||'pending';return `<div class="message-row"><div class="message-copy"><strong>${esc(x.name)} <span class="pill">${esc(x.paymentMethod||'PAYMENT')}</span> <span class="pill">${esc(st.toUpperCase())}</span></strong><small>${esc(x.email)} • ${esc(x.budget||'')}</small><small style="color:#b6becb">${esc(x.message)}</small></div><div class="message-time">${timeAgo(x.createdAt)}</div><div class="actions"><a class="btn" target="_blank" rel="noopener" href="/payment-voucher.html?id=${encodeURIComponent(x.id)}">Voucher</a><button class="btn green" onclick="setPaymentStatus('${x.id}','paid')">Mark Paid</button><button class="btn danger" onclick="setPaymentStatus('${x.id}','cancelled')">Cancel</button></div></div>`}).join('')||'<p class="muted" style="padding:14px">No payment requests yet.</p>'}
async function setPaymentStatus(id,status){await api('/api/admin/messages/'+id,{method:'PATCH',body:JSON.stringify({status})});await load();tab('transactions');toast(status==='paid'?'Payment marked paid ✓':'Payment cancelled')}
async function persistOrder(type,items){sortBusy=true;try{await api('/api/admin/'+type+'/reorder',{method:'POST',body:JSON.stringify({ids:items.map(x=>x.id)})});toast('Order saved ✓')}catch(e){toast(e.message);await load()}finally{sortBusy=false}}
function bindSortable(root,type){if(!root||root.dataset.sortBound)return;root.dataset.sortBound='1';root.addEventListener('dragstart',e=>{const item=e.target.closest('.sortable-item');if(!item)return;dragState={type,item};item.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',item.dataset.sortId||'')});root.addEventListener('dragover',e=>{const item=e.target.closest('.sortable-item');if(!item||!dragState||dragState.type!==type||item===dragState.item)return;e.preventDefault();item.classList.add('drag-over');const r=item.getBoundingClientRect();root.insertBefore(dragState.item,e.clientY<r.top+r.height/2?item:item.nextSibling)});root.addEventListener('drop',async e=>{if(!dragState||dragState.type!==type)return;e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const ids=[...root.querySelectorAll('.sortable-item')].map(x=>String(x.dataset.sortId));const source=type==='projects'?D.projects:D.testimonials;const ordered=ids.map(id=>source.find(x=>String(x.id)===id)).filter(Boolean);if(type==='projects')D.projects=ordered;else D.testimonials=ordered;const item=dragState.item;dragState=null;item.classList.remove('dragging');await persistOrder(type,ordered);renderDashboard()});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(dragState?.item){dragState.item.classList.remove('dragging');dragState=null}})}
function bindSkillSortable(root){if(!root||root.dataset.sortBound)return;root.dataset.sortBound='1';root.addEventListener('dragstart',e=>{const item=e.target.closest('.sortable-item');if(!item)return;dragState={type:'skills',item};item.classList.add('dragging');e.dataTransfer.effectAllowed='move'});root.addEventListener('dragover',e=>{const item=e.target.closest('.sortable-item');if(!item||!dragState||dragState.type!=='skills'||item===dragState.item)return;e.preventDefault();item.classList.add('drag-over');const r=item.getBoundingClientRect();root.insertBefore(dragState.item,e.clientY<r.top+r.height/2?item:item.nextSibling)});root.addEventListener('drop',async e=>{if(!dragState||dragState.type!=='skills')return;e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const value=readCollection('skillsEditor','skills');const names=[...root.querySelectorAll('.sortable-item')].map(r=>r.dataset.sortKey);const reordered=names.map(n=>value.find(x=>x.name===n)).filter(Boolean);const item=dragState.item;dragState=null;item.classList.remove('dragging');sortBusy=true;try{const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({skills:reordered})});D.settings=out;toast('Skills order saved ✓')}catch(e){toast(e.message);await load()}finally{sortBusy=false}});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(dragState?.item){dragState.item.classList.remove('dragging');dragState=null}})}
function formHtml(type,x={}){if(type==='service')return `<input type="hidden" id="eid" value="${esc(x.id||'')}"><label>Service title<input class="field" id="titlef" required value="${esc(x.title||'')}"></label><label>Description<textarea class="field" id="desc">${esc(x.description||'')}</textarea></label><label><input id="enabled" type="checkbox" ${x.enabled!==false?'checked':''}> Visible on website</label><button class="btn" style="margin-top:10px">Save service</button>`;if(type==='project')return `<input type="hidden" id="eid" value="${esc(x.id||'')}"><div class="form-grid"><label>Title<input class="field" id="titlef" required value="${esc(x.title||'')}"></label><label>Category<input class="field" id="cat" value="${esc(x.category||'')}"></label><label>Role<input class="field" id="role" value="${esc(x.role||'')}"></label><label>Case study URL<input class="field" id="case" value="${esc(x.caseStudy||'')}"></label><label class="full">Description<textarea class="field" id="desc">${esc(x.description||'')}</textarea></label><label>Live URL<input class="field" id="live" value="${esc(x.live||'')}"></label><label>Cover image<input id="img" class="field" type="file" accept="image/*"></label><label><input id="featured" type="checkbox" ${x.featured?'checked':''}> Featured</label><label><input id="published" type="checkbox" ${x.published!==false?'checked':''}> Published</label></div><button class="btn" style="margin-top:10px">Save project</button>`;return `<input type="hidden" id="eid" value="${esc(x.id||'')}"><div class="form-grid"><label>Client name<input class="field" id="titlef" required value="${esc(x.name||'')}"></label><label>Professional title / Role<input class="field" id="role" value="${esc(x.role||'')}"></label><label>Rating<input class="field" id="rating" type="number" min="1" max="5" step=".1" value="${x.rating??4.9}"></label><label>Location<input class="field" id="location" value="${esc(x.location||'')}"></label><label>Avatar<input id="img" class="field" type="file" accept="image/*"></label><label>Flag SVG URL<input class="field" id="flagSvg" value="${esc(x.flagSvg||'')}"></label><label class="full">Testimonial<textarea class="field" id="desc" required>${esc(x.text||'')}</textarea></label><label class="full"><input id="published" type="checkbox" ${x.published!==false?'checked':''}> Published</label></div><button class="btn" style="margin-top:10px">Save testimonial</button>`}
function openProject(id){const x=D.projects.find(p=>p.id===id)||{};$('#modalTitle').textContent=id?'Edit Project':'Add Project';$('#entityForm').innerHTML=formHtml('project',x);$('#entityForm').onsubmit=e=>saveEntity(e,'project');$('#modal').classList.add('open')}
function openTestimonial(id){const x=D.testimonials.find(t=>t.id===id)||{};$('#modalTitle').textContent=id?'Edit Testimonial':'Add Testimonial';$('#entityForm').innerHTML=formHtml('test',x);$('#entityForm').onsubmit=e=>saveEntity(e,'test');$('#modal').classList.add('open')}
function editService(i){const x=(D.settings.services||[])[i]||{};$('#modalTitle').textContent='Edit Service';$('#entityForm').innerHTML=formHtml('service',x);$('#entityForm').onsubmit=async e=>{e.preventDefault();let arr=[...(D.settings.services||[])];arr[i]={title:$('#titlef').value,description:$('#desc').value,enabled:$('#enabled').checked};await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({services:arr})});closeModal();await load();toast('Service updated')}}
function removeService(i){if(!confirm('Delete this service?'))return;let arr=[...(D.settings.services||[])];arr.splice(i,1);api('/api/admin/settings',{method:'PUT',body:JSON.stringify({services:arr})}).then(()=>{load();toast('Service deleted')})}
function openService(){openServiceAdd()};function openServiceAdd(){$('#modalTitle').textContent='Add Service';$('#entityForm').innerHTML=formHtml('service',{});$('#entityForm').onsubmit=async e=>{e.preventDefault();let arr=[...(D.settings.services||[])];arr.push({title:$('#titlef').value,description:$('#desc').value,enabled:$('#enabled').checked});await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({services:arr})});closeModal();await load();toast('Service added')}}
async function saveEntity(e,type){e.preventDefault();try{const id=$('#eid').value;let b={},f=$('#img')?.files?.[0];if(type==='project')b={title:$('#titlef').value,category:$('#cat').value,role:$('#role').value,description:$('#desc').value,caseStudy:$('#case').value,live:$('#live').value,featured:$('#featured').checked,published:$('#published').checked};else b={name:$('#titlef').value,role:$('#role').value,text:$('#desc').value,rating:Number($('#rating').value),location:$('#location').value,flagSvg:$('#flagSvg').value,published:$('#published').checked};if(f){b.imageData=await dataUrl(f);b.imageName=f.name}const path='/api/admin/'+(type==='project'?'projects':'testimonials');await api(path+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(b)});closeModal();await load();toast('Saved successfully')}catch(e){toast(e.message)}}
function dataUrl(f){return new Promise((ok,no)=>{const r=new FileReader;r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)})}
async function del(type,id){if(!confirm('Delete this item?'))return;await api('/api/admin/'+type+'/'+id,{method:'DELETE'});await load();toast('Deleted')}
function closeModal(){$('#modal').classList.remove('open')}
function bindMarqueeSortable(root){if(!root||root.dataset.sortBound)return;root.dataset.sortBound='1';root.addEventListener('dragstart',e=>{const item=e.target.closest('.sortable-item');if(!item)return;dragState={type:'marquee',item};item.classList.add('dragging');e.dataTransfer.effectAllowed='move'});root.addEventListener('dragover',e=>{const item=e.target.closest('.sortable-item');if(!item||!dragState||dragState.type!=='marquee'||item===dragState.item)return;e.preventDefault();item.classList.add('drag-over');const r=item.getBoundingClientRect();root.insertBefore(dragState.item,e.clientY<r.top+r.height/2?item:item.nextSibling)});root.addEventListener('drop',async e=>{if(!dragState||dragState.type!=='marquee')return;e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const value=readCollection('marqueeEditor','marquee');const ids=[...root.querySelectorAll('.sortable-item')].map(r=>r.dataset.sortKey);const reordered=ids.map(k=>value.find(x=>x.id===k)).filter(Boolean);const item=dragState.item;dragState=null;item.classList.remove('dragging');sortBusy=true;try{const out=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({marqueeLogos:reordered})});D.settings=out;toast('Logo order saved ✓')}catch(e){toast(e.message);await load()}finally{sortBusy=false}});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(dragState?.item){dragState.item.classList.remove('dragging');dragState=null}})}
function collectionRows(id,items,type){const root=$('#'+id);if(!root)return;root.innerHTML='';if(!items||!items.length){root.innerHTML='<div class="collection-empty">No items yet. Add your first item below.</div>';return}items.forEach((x,i)=>{const row=document.createElement('div');row.className='collection-row'+(type==='skills'||type==='marquee'?' sortable-item':'');if(type==='skills'){row.draggable=true;row.dataset.sortIndex=i;row.dataset.sortKey=x.name||'';row.innerHTML=`<span class="sortable-handle">Drag</span><div><span class="mini-label">Skill name</span><input class="field c-name" value="${esc(x.name||'')}"></div><div><span class="mini-label">Description</span><input class="field c-desc" value="${esc(x.description||'')}"></div><div class="percent"><span class="mini-label">Percent</span><input class="field c-percent" type="number" min="0" max="100" value="${Number(x.percent||0)}"></div><button class="btn remove" type="button">Remove</button>`}else if(type==='nav')row.innerHTML=`<div><span class="mini-label">Label</span><input class="field c-label" value="${esc(x.label||'')}"></div><div><span class="mini-label">Link / anchor</span><input class="field c-href" value="${esc(x.href||'')}"></div><div class="switch-wrap"><input class="switch c-enabled" type="checkbox" ${x.enabled!==false?'checked':''}> Visible</div><button class="btn remove" type="button">Remove</button>`;else if(type==='marquee'){row.draggable=true;row.dataset.sortIndex=i;row.dataset.sortKey=x.id||('ml'+i);row.innerHTML=`<span class="sortable-handle">Drag</span><img class="marquee-thumb" src="${esc(x.logo||'')}" alt="" style="width:44px;height:44px;object-fit:contain;background:rgba(255,255,255,.04);border-radius:8px;border:1px solid rgba(255,255,255,.08)"><div><span class="mini-label">Company name</span><input class="field c-name" value="${esc(x.name||'')}"></div><div style="flex:1.6"><span class="mini-label">Logo image / SVG URL</span><input class="field c-logo" value="${esc(x.logo||'')}"></div><div class="switch-wrap"><input class="switch c-enabled" type="checkbox" ${x.enabled!==false?'checked':''}> Visible</div><button class="btn remove" type="button">Remove</button>`;row.querySelector('.c-logo').addEventListener('input',e=>{row.querySelector('.marquee-thumb').src=e.target.value})}else row.innerHTML=`<div><span class="mini-label">Value</span><input class="field c-value" value="${esc(x.value||'')}"></div><div><span class="mini-label">Label</span><input class="field c-label" value="${esc(x.label||'')}"></div><div></div><button class="btn remove" type="button">Remove</button>`;row.querySelector('.remove').onclick=()=>{items.splice(i,1);collectionRows(id,items,type)};root.appendChild(row)});if(type==='skills')bindSkillSortable(root);if(type==='marquee')bindMarqueeSortable(root)}
function readCollection(id,type){return [...document.querySelectorAll('#'+id+' .collection-row')].map((r,i)=>type==='skills'?{name:r.querySelector('.c-name').value.trim(),description:r.querySelector('.c-desc').value.trim(),percent:Number(r.querySelector('.c-percent').value||0)}:type==='nav'?{label:r.querySelector('.c-label').value.trim(),href:r.querySelector('.c-href').value.trim(),enabled:r.querySelector('.c-enabled').checked}:type==='marquee'?{id:r.dataset.sortKey||('ml'+i),name:r.querySelector('.c-name').value.trim(),logo:r.querySelector('.c-logo').value.trim(),enabled:r.querySelector('.c-enabled').checked}:{value:r.querySelector('.c-value').value.trim(),label:r.querySelector('.c-label').value.trim()}).filter(x=>type==='skills'?x.name:type==='nav'?x.label:type==='marquee'?(x.name||x.logo):x.label)}
function buildCollectionEditors(){collectionRows('skillsEditor',JSON.parse(JSON.stringify(D.settings?.skills||[])),'skills');collectionRows('navEditor',JSON.parse(JSON.stringify(D.settings?.navItems||[])),'nav');collectionRows('metricsEditor',JSON.parse(JSON.stringify(D.settings?.metrics||[])),'metrics');collectionRows('marqueeEditor',JSON.parse(JSON.stringify(D.settings?.marqueeLogos||[])),'marquee');const mf=$('#marqueeEyebrowField');if(mf)mf.value=D.settings?.marqueeEyebrow||''}
function buildFlowEditors(){
  const ptf=$('#processTitleField');if(ptf)ptf.value=D.settings?.processTitle||'';
  const pdf=$('#processDescField');if(pdf)pdf.value=D.settings?.processDescription||'';
  renderProcessEditor(JSON.parse(JSON.stringify(D.settings?.processSteps||[])));
  renderMetricsEditor2(JSON.parse(JSON.stringify(D.settings?.metrics||[])));
  renderEstimatorEditor(JSON.parse(JSON.stringify(D.settings?.estimatorGroups||[])));
}
function bindSimpleSortable(root,type,saveKey){if(!root||root.dataset.flowSortBound)return;root.dataset.flowSortBound='1';let dragged=null;root.addEventListener('dragstart',e=>{const x=e.target.closest('[draggable="true"]');if(!x)return;dragged=x;x.classList.add('dragging');e.dataTransfer.effectAllowed='move'});root.addEventListener('dragover',e=>{const x=e.target.closest('[draggable="true"]');if(!dragged||!x||x===dragged)return;e.preventDefault();x.classList.add('drag-over');const r=x.getBoundingClientRect();root.insertBefore(dragged,e.clientY<r.top+r.height/2?x:x.nextSibling)});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(dragged){dragged.classList.remove('dragging');dragged=null}})}
function renderProcessEditor(items){const root=$('#processEditor');if(!root)return;root.innerHTML=(items||[]).map((x,i)=>`<div class="flow-group process-edit" draggable="true" data-index="${i}"><div class="flow-group-head"><span class="flow-drag">↕</span><div><span class="mini-label">Title</span><input class="field p-title" value="${esc(x.title||'')}"></div><div><span class="mini-label">Step</span><input class="field p-step" value="${i+1}" readonly></div><div><span class="mini-label">Description</span><input class="field p-desc" value="${esc(x.description||'')}"></div><button class="btn remove p-remove" type="button">Remove</button></div></div>`).join('')||'<div class="collection-empty">No process cards yet.</div>';root.querySelectorAll('.p-remove').forEach(b=>b.onclick=()=>{b.closest('.process-edit').remove()});bindSimpleSortable(root,'process','processSteps')}
function readProcessEditor(){return [...document.querySelectorAll('#processEditor .process-edit')].map((r,i)=>({title:r.querySelector('.p-title').value.trim(),description:r.querySelector('.p-desc').value.trim()})).filter(x=>x.title)}
function renderMetricsEditor2(items){const root=$('#metricsEditor2');if(!root)return;root.innerHTML=(items||[]).map((x,i)=>`<div class="flow-group metric-edit" draggable="true"><div class="flow-group-head"><span class="flow-drag">↕</span><div><span class="mini-label">Value</span><input class="field m-value" value="${esc(x.value||'')}"></div><div style="grid-column:span 2"><span class="mini-label">Label</span><input class="field m-label" value="${esc(x.label||'')}"></div><button class="btn remove m-remove" type="button">Remove</button></div></div>`).join('')||'<div class="collection-empty">No metrics yet.</div>';root.querySelectorAll('.m-remove').forEach(b=>b.onclick=()=>b.closest('.metric-edit').remove());bindSimpleSortable(root,'metrics','metrics')}
function readMetricsEditor2(){return [...document.querySelectorAll('#metricsEditor2 .metric-edit')].map(r=>({value:r.querySelector('.m-value').value.trim(),label:r.querySelector('.m-label').value.trim()})).filter(x=>x.label)}
function renderEstimatorEditor(groups){const root=$('#estimatorEditor');if(!root)return;root.innerHTML=(groups||[]).map((g,gi)=>`<div class="flow-group estimator-edit" draggable="true" data-group-index="${gi}" data-group-id="${esc(g.id||("group"+gi))}"><div class="flow-group-head"><span class="flow-drag">↕</span><div><span class="mini-label">Group title</span><input class="field e-title" value="${esc(g.title||'')}"></div><div><span class="mini-label">Mode</span><select class="field e-mode"><option value="single" ${g.mode==='single'?'selected':''}>Single</option><option value="multi" ${g.mode==='multi'?'selected':''}>Multi</option></select></div><div><span class="mini-label">Summary label</span><input class="field e-summary" value="${esc(g.summaryLabel||'')}"></div><button class="btn remove e-remove" type="button">Remove</button></div><div class="flow-options">${(g.options||[]).map((o,oi)=>`<div class="flow-option" draggable="true"><span class="flow-drag">↕</span><div><span class="mini-label">Option label</span><input class="field o-label" value="${esc(o.label||'')}"></div><div><span class="mini-label">Price</span><input class="field o-price" type="number" step="0.01" value="${o.price??''}"></div><div><span class="mini-label">Multiplier</span><input class="field o-mult" type="number" step="0.01" value="${o.mult??''}"></div><div><span class="mini-label">Add-on</span><input class="field o-add" type="number" step="0.01" value="${o.add??''}"></div><button class="btn remove o-remove" type="button">Remove</button><input class="field o-days flow-wide" placeholder="Days e.g. 10–14" value="${esc(o.days||'')}"></div>`).join('')}</div><button class="btn ghost flow-add e-add-option" type="button">＋ Add Option</button></div>`).join('')||'<div class="collection-empty">No estimator groups yet.</div>';root.querySelectorAll('.e-remove').forEach(b=>b.onclick=()=>b.closest('.estimator-edit').remove());root.querySelectorAll('.o-remove').forEach(b=>b.onclick=()=>b.closest('.flow-option').remove());root.querySelectorAll('.e-add-option').forEach(b=>b.onclick=()=>{const box=b.previousElementSibling;const r=document.createElement('div');r.className='flow-option';r.draggable=true;r.innerHTML='<span class="flow-drag">↕</span><div><span class="mini-label">Option label</span><input class="field o-label" value="New Option"></div><div><span class="mini-label">Price</span><input class="field o-price" type="number"></div><div><span class="mini-label">Multiplier</span><input class="field o-mult" type="number" step="0.01"></div><div><span class="mini-label">Add-on</span><input class="field o-add" type="number"></div><button class="btn remove o-remove" type="button">Remove</button><input class="field o-days flow-wide" placeholder="Days e.g. 10–14">';r.querySelector('.o-remove').onclick=()=>r.remove();box.appendChild(r);bindNestedSortable(box)});root.querySelectorAll('.flow-options').forEach(bindNestedSortable);bindSimpleSortable(root,'estimator','estimatorGroups')}
function bindNestedSortable(root){if(root.dataset.sortBound)return;root.dataset.sortBound='1';let d=null;root.addEventListener('dragstart',e=>{d=e.target.closest('.flow-option');if(d){d.classList.add('dragging');e.dataTransfer.effectAllowed='move'}});root.addEventListener('dragover',e=>{const t=e.target.closest('.flow-option');if(!d||!t||t===d)return;e.preventDefault();t.classList.add('drag-over');const r=t.getBoundingClientRect();root.insertBefore(d,e.clientY<r.top+r.height/2?t:t.nextSibling)});root.addEventListener('dragend',()=>{root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));if(d){d.classList.remove('dragging');d=null}})}
function readEstimatorEditor(){return [...document.querySelectorAll('#estimatorEditor .estimator-edit')].map((g,gi)=>({id:g.dataset.groupId||('group'+gi),title:g.querySelector('.e-title').value.trim(),mode:g.querySelector('.e-mode').value,summaryLabel:g.querySelector('.e-summary').value.trim(),options:[...g.querySelectorAll('.flow-option')].map((o,oi)=>{const v=(sel)=>o.querySelector(sel).value.trim();const x={id:(g.dataset.groupId||'g')+'-'+oi,label:v('.o-label')};const p=v('.o-price'),m=v('.o-mult'),a=v('.o-add'),days=v('.o-days');if(p)x.price=Number(p);if(m)x.mult=Number(m);if(a)x.add=Number(a);if(days)x.days=days;return x}).filter(x=>x.label)})) .filter(x=>x.title)}

